// Rebuilds src/sandbox/runtime-bundle.js from the installed @abaplint/runtime.
//
// The bundle is committed rather than built by Vite because it is loaded as a
// plain <script> inside the execution Worker's blob: URL (see CLAUDE.md), so it
// has to be a self-contained IIFE that defines the `abaplintRuntime` global.
// Run this after bumping @abaplint/runtime — the transpiler emits calls the
// runtime must already implement, and a stale bundle turns a clean
// transpile_error into a runtime crash.
//
//   node scripts/build-runtime-bundle.mjs
//   node scripts/build-runtime-bundle.mjs --check   (fails if out of date)

import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const OUT = "src/sandbox/runtime-bundle.js";
const check = process.argv.includes("--check");

const version = require("@abaplint/runtime/package.json").version;

const result = await build({
  entryPoints: ["node_modules/@abaplint/runtime/build/src/index.js"],
  bundle: true,
  format: "iife",
  globalName: "abaplintRuntime",
  platform: "browser",
  write: false,
});

const banner = `// Generated by scripts/build-runtime-bundle.mjs from @abaplint/runtime@${version}. Do not edit.\n`;
const next = banner + result.outputFiles[0].text;

if (check) {
  const current = await readFile(OUT, "utf8").catch(() => "");
  if (current !== next) {
    console.error(
      `${OUT} is out of date for @abaplint/runtime@${version}.\n` +
        "Run: node scripts/build-runtime-bundle.mjs",
    );
    process.exit(1);
  }
  console.log(`${OUT} is up to date (@abaplint/runtime@${version})`);
} else {
  await writeFile(OUT, next);
  console.log(`Wrote ${OUT} from @abaplint/runtime@${version} (${next.length} bytes)`);
}
